//! F32×F32 AVX-512F (x86_64, zmm) matmul kernel.
//!
//! Generated by `avx512_matmul_packed!` / `avx512_matmul_packed_tiled!` in
//! `super::super::simd_avx512`.  F32 weight bytes are reinterpreted as
//! `&[f32]` so no dequant step is required (16 lanes per zmm load).
//! Dispatch prefers this kernel when `n_in % 16 == 0` and falls back to the
//! AVX2 kernel for multiples of 8.

use crate::{avx512_matmul_packed, avx512_matmul_packed_tiled};

#[target_feature(enable = "avx512f", enable = "fma")]
unsafe fn unpack_f32_16(w: *const u8, row_byte: usize, col: usize) -> std::arch::x86_64::__m512 {
    use std::arch::x86_64::*;
    _mm512_loadu_ps(w.add(row_byte + col * 4) as *const f32)
}

#[target_feature(enable = "avx512f", enable = "fma")]
unsafe fn scalar_unpack_f32(w: *const u8, row_byte: usize, col: usize) -> f32 {
    *(w.add(row_byte + col * 4) as *const f32)
}

avx512_matmul_packed!(
    matmul_f32_vs_f32_avx512,
    4,
    unpack_f32_16,
    scalar_unpack_f32
);

avx512_matmul_packed_tiled!(
    matmul_f32_vs_f32_avx512_tiled,
    4,
    unpack_f32_16,
    scalar_unpack_f32
);

#[cfg(test)]
mod tests {
    use super::{matmul_f32_vs_f32_avx512, matmul_f32_vs_f32_avx512_tiled};
    use crate::ops::kernel::f32::scalar::forward_f32_rows;

    fn assert_avx512_eq_scalar(
        label: &str,
        weight: &[f32],
        input: &[f32],
        n_in: usize,
        n_out: usize,
    ) {
        let mut avx512_out = vec![0.0f32; n_out];
        let mut scalar_out = vec![0.0f32; n_out];
        let weight_bytes: &[u8] = bytemuck::cast_slice(weight);
        unsafe {
            matmul_f32_vs_f32_avx512(weight_bytes, input, &mut avx512_out, n_in, 0, n_out);
        }
        forward_f32_rows(weight, input, &mut scalar_out, n_in, n_out, 0, 1);
        for (i, (a, s)) in avx512_out.iter().zip(scalar_out.iter()).enumerate() {
            let denom = s.abs().max(1e-3);
            let rel = (a - s).abs() / denom;
            assert!(
                rel < 1e-3 || (a - s).abs() < 1e-4,
                "{} row {}: avx512={} scalar={} diff={}",
                label,
                i,
                a,
                s,
                (a - s).abs(),
            );
        }
    }

    #[test]
    fn avx512_matches_scalar_small() {
        let n_in = 16;
        let n_out = 4;
        let weight: Vec<f32> = (0..n_in * n_out).map(|i| (i as f32 * 0.1) - 0.3).collect();
        let input: Vec<f32> = (0..n_in).map(|i| (i as f32 - 8.0) * 0.05).collect();
        assert_avx512_eq_scalar("small 4x16", &weight, &input, n_in, n_out);
    }

    #[test]
    fn avx512_matches_scalar_large() {
        let n_in = 256;
        let n_out = 16;
        let weight: Vec<f32> = (0..n_in * n_out)
            .map(|i| (((i * 13 + 7) % 47) as f32 - 23.0) * 0.01)
            .collect();
        let input: Vec<f32> = (0..n_in).map(|i| ((i % 23) as f32 - 11.0) * 0.02).collect();
        assert_avx512_eq_scalar("large 16x256", &weight, &input, n_in, n_out);
    }

    #[test]
    fn avx512_matches_scalar_tail() {
        let n_in = 40;
        let n_out = 3;
        let weight: Vec<f32> = (0..n_in * n_out)
            .map(|i| ((i * 17) as f32 * 0.013).sin())
            .collect();
        let input: Vec<f32> = (0..n_in).map(|i| (i as f32 - 20.0) * 0.03).collect();
        assert_avx512_eq_scalar("tail 3x40", &weight, &input, n_in, n_out);
    }

    /// The tiled kernel must be bit-identical to the per-token kernel: same
    /// dot body, only the loop nesting changes. Shapes cross both the
    /// 32-row and 32-token tile boundaries with `n_in` a multiple of 16.
    #[test]
    fn avx512_tiled_matches_per_token_bits() {
        let n_in = 192usize;
        let n_out = 70usize;
        let rows = 33usize;
        let weight: Vec<f32> = (0..n_in * n_out)
            .map(|i| (((i * 31 + 5) % 97) as f32 - 48.0) / 32.0)
            .collect();
        let input: Vec<f32> = (0..rows * n_in)
            .map(|i| (((i * 29 + 3) % 89) as f32 - 44.0) / 32.0)
            .collect();
        let weight_bytes: &[u8] = bytemuck::cast_slice(&weight);

        let mut expected = vec![0.0f32; rows * n_out];
        for (input_row, output_row) in input
            .chunks_exact(n_in)
            .zip(expected.chunks_exact_mut(n_out))
        {
            unsafe {
                matmul_f32_vs_f32_avx512(weight_bytes, input_row, output_row, n_in, 0, n_out);
            }
        }

        let mut actual = vec![0.0f32; rows * n_out];
        unsafe {
            matmul_f32_vs_f32_avx512_tiled(
                weight_bytes,
                &input,
                &mut actual,
                n_in,
                n_out,
                rows,
                0,
                n_out,
            );
        }
        for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
            assert_eq!(
                a.to_bits(),
                e.to_bits(),
                "row {}/{}: tiled={} per-token={}",
                i % n_out,
                i / n_out,
                a,
                e
            );
        }
    }

    /// Perf probe (explicit run): zmm vs ymm on a decoder-shaped F32 matmul,
    /// per-token and token-tiled. release-fast numbers are only comparable
    /// to each other (same profile); see fast-profile-iteration notes.
    #[test]
    #[ignore]
    fn avx512_vs_avx2_perf_probe() {
        use super::{matmul_f32_vs_f32_avx512, matmul_f32_vs_f32_avx512_tiled};
        use crate::ops::kernel::f32::avx2::matmul_f32_vs_f32_avx2;
        use crate::ops::kernel::f32::avx2::matmul_f32_vs_f32_avx2_tiled;

        let n_in = 2048usize;
        let n_out = 1024usize;
        let tokens = 64usize;
        let weight: Vec<f32> = (0..n_in * n_out)
            .map(|i| ((i * 31 % 97) as f32 - 48.0) / 32.0)
            .collect();
        let input: Vec<f32> = (0..tokens * n_in)
            .map(|i| ((i * 29 % 89) as f32 - 44.0) / 32.0)
            .collect();
        let weight_bytes: &[u8] = bytemuck::cast_slice(&weight);
        let flops = 2.0 * (n_in as f64) * (n_out as f64);

        let mut out = vec![0.0f32; n_out];
        unsafe {
            matmul_f32_vs_f32_avx2(weight_bytes, &input[..n_in], &mut out, n_in, 0, n_out);
            matmul_f32_vs_f32_avx512(weight_bytes, &input[..n_in], &mut out, n_in, 0, n_out);
        }
        let mut batched = vec![0.0f32; tokens * n_out];
        unsafe {
            matmul_f32_vs_f32_avx2_tiled(
                weight_bytes,
                &input,
                &mut batched,
                n_in,
                n_out,
                tokens,
                0,
                n_out,
            );
            matmul_f32_vs_f32_avx512_tiled(
                weight_bytes,
                &input,
                &mut batched,
                n_in,
                n_out,
                tokens,
                0,
                n_out,
            );
        }

        let repeats = 20usize;
        let t = std::time::Instant::now();
        for _ in 0..repeats {
            unsafe {
                matmul_f32_vs_f32_avx2(
                    std::hint::black_box(weight_bytes),
                    std::hint::black_box(&input[..n_in]),
                    std::hint::black_box(&mut out),
                    n_in,
                    0,
                    n_out,
                );
            }
        }
        let avx2_ms = t.elapsed().as_secs_f64() * 1000.0 / repeats as f64;
        let t = std::time::Instant::now();
        for _ in 0..repeats {
            unsafe {
                matmul_f32_vs_f32_avx512(
                    std::hint::black_box(weight_bytes),
                    std::hint::black_box(&input[..n_in]),
                    std::hint::black_box(&mut out),
                    n_in,
                    0,
                    n_out,
                );
            }
        }
        let avx512_ms = t.elapsed().as_secs_f64() * 1000.0 / repeats as f64;

        let t = std::time::Instant::now();
        for _ in 0..repeats {
            unsafe {
                matmul_f32_vs_f32_avx2_tiled(
                    std::hint::black_box(weight_bytes),
                    std::hint::black_box(&input),
                    std::hint::black_box(&mut batched),
                    n_in,
                    n_out,
                    tokens,
                    0,
                    n_out,
                );
            }
        }
        let avx2_tiled_ms = t.elapsed().as_secs_f64() * 1000.0 / repeats as f64;
        let t = std::time::Instant::now();
        for _ in 0..repeats {
            unsafe {
                matmul_f32_vs_f32_avx512_tiled(
                    std::hint::black_box(weight_bytes),
                    std::hint::black_box(&input),
                    std::hint::black_box(&mut batched),
                    n_in,
                    n_out,
                    tokens,
                    0,
                    n_out,
                );
            }
        }
        let avx512_tiled_ms = t.elapsed().as_secs_f64() * 1000.0 / repeats as f64;

        println!(
            "per-token: avx2 {avx2_ms:.3} ms ({:.2} GFLOPS) | avx512 {avx512_ms:.3} ms ({:.2} GFLOPS) | {:.2}x",
            flops / (avx2_ms * 1e-3) / 1e9,
            flops / (avx512_ms * 1e-3) / 1e9,
            avx2_ms / avx512_ms,
        );
        println!(
            "tiled x{tokens}: avx2 {avx2_tiled_ms:.3} ms ({:.2} GFLOPS) | avx512 {avx512_tiled_ms:.3} ms ({:.2} GFLOPS) | {:.2}x",
            tokens as f64 * flops / (avx2_tiled_ms * 1e-3) / 1e9,
            tokens as f64 * flops / (avx512_tiled_ms * 1e-3) / 1e9,
            avx2_tiled_ms / avx512_tiled_ms,
        );

        // Compute-bound shape: weight panel fits L2 so the tiled kernel is
        // FMA-throughput limited rather than bandwidth limited.
        let n_in = 512usize;
        let n_out = 512usize;
        let tokens = 64usize;
        let weight: Vec<f32> = (0..n_in * n_out)
            .map(|i| ((i * 31 % 97) as f32 - 48.0) / 32.0)
            .collect();
        let input: Vec<f32> = (0..tokens * n_in)
            .map(|i| ((i * 29 % 89) as f32 - 44.0) / 32.0)
            .collect();
        let weight_bytes: &[u8] = bytemuck::cast_slice(&weight);
        let flops = 2.0 * (n_in as f64) * (n_out as f64);
        let mut batched = vec![0.0f32; tokens * n_out];
        unsafe {
            matmul_f32_vs_f32_avx2_tiled(
                weight_bytes,
                &input,
                &mut batched,
                n_in,
                n_out,
                tokens,
                0,
                n_out,
            );
            matmul_f32_vs_f32_avx512_tiled(
                weight_bytes,
                &input,
                &mut batched,
                n_in,
                n_out,
                tokens,
                0,
                n_out,
            );
        }
        let repeats = 50usize;
        let t = std::time::Instant::now();
        for _ in 0..repeats {
            unsafe {
                matmul_f32_vs_f32_avx2_tiled(
                    std::hint::black_box(weight_bytes),
                    std::hint::black_box(&input),
                    std::hint::black_box(&mut batched),
                    n_in,
                    n_out,
                    tokens,
                    0,
                    n_out,
                );
            }
        }
        let avx2_l2_ms = t.elapsed().as_secs_f64() * 1000.0 / repeats as f64;
        let t = std::time::Instant::now();
        for _ in 0..repeats {
            unsafe {
                matmul_f32_vs_f32_avx512_tiled(
                    std::hint::black_box(weight_bytes),
                    std::hint::black_box(&input),
                    std::hint::black_box(&mut batched),
                    n_in,
                    n_out,
                    tokens,
                    0,
                    n_out,
                );
            }
        }
        let avx512_l2_ms = t.elapsed().as_secs_f64() * 1000.0 / repeats as f64;
        println!(
            "l2-resident tiled x{tokens}: avx2 {avx2_l2_ms:.3} ms ({:.2} GFLOPS) | avx512 {avx512_l2_ms:.3} ms ({:.2} GFLOPS) | {:.2}x",
            tokens as f64 * flops / (avx2_l2_ms * 1e-3) / 1e9,
            tokens as f64 * flops / (avx512_l2_ms * 1e-3) / 1e9,
            avx2_l2_ms / avx512_l2_ms,
        );
    }
}
